// src/engine/calendarEvents.ts
function buildCalendarEventsForMonth(state, yearMonth) {
	const map = /* @__PURE__ */ new Map();
	const totalDays = daysInMonth(`${yearMonth}-01`);
	const monthStart = `${yearMonth}-01`;
	const monthEnd = `${yearMonth}-${String(totalDays).padStart(2, "0")}`;
	const push = (ev) => {
		const arr = map.get(ev.date) ?? [];
		arr.push(ev);
		map.set(ev.date, arr);
	};
	for (const tx of state.transactions) {
		if (tx.isVoided) continue;
		if (tx.date >= monthStart && tx.date <= monthEnd) {
			const cat = state.categories.find((c) => c.id === tx.categoryId)?.name;
			push({
				id: `tx-${tx.id}`,
				date: tx.date,
				type: tx.type === "income" ? "income" : "expense",
				title: tx.description,
				amount: tx.amount,
				detail: cat
			});
		}
	}
	for (const d of state.debts) if (d.status === "active" && d.dueDate && d.dueDate >= monthStart && d.dueDate <= monthEnd) {
		const isReceivable = d.direction === "receivable";
		push({
			id: `debt-${d.id}`,
			date: d.dueDate,
			type: isReceivable ? "receivable_due" : "debt_due",
			title: isReceivable ? `Jatuh tempo piutang: ${d.creditor}` : `Jatuh tempo utang: ${d.creditor}`,
			amount: d.remainingAmount,
			detail: d.description
		});
	}
	for (const ob of state.obligations) {
		if (ob.status !== "active" || ob.isArchived) continue;
		let cursor = ob.nextDueDate;
		let guard = 0;
		while (cursor <= monthEnd && guard < 12) {
			guard++;
			const withinEnd = !ob.endDate || cursor <= ob.endDate;
			const withinStart = cursor >= ob.startDate;
			if (cursor >= monthStart && withinStart && withinEnd) {
				const isSched = ob.kind === "scheduled_expense";
				push({
					id: `ob-${ob.id}-${cursor}`,
					date: cursor,
					type: isSched ? "scheduled_expense_due" : "obligation_due",
					title: `${isSched ? "Pengeluaran Terjadwal" : "Kewajiban"}: ${ob.name}`,
					amount: ob.amount,
					detail: ob.reservedAmount >= ob.amount ? "Dana cadangan siap" : `Perlu cadangan Rp${(ob.amount - ob.reservedAmount).toLocaleString("id-ID")}`
				});
			}
			if (ob.frequency === "once") break;
			cursor = ob.frequency === "weekly" ? addDaysISO(cursor, 7) : ob.frequency === "yearly" ? addDaysISO(cursor, 365) : addDaysISO(cursor, 30);
		}
	}
	for (const pay of state.projectPayments) if (pay.status === "expected" && pay.expectedDate && pay.expectedDate >= monthStart && pay.expectedDate <= monthEnd) {
		const proj = state.projects.find((p) => p.id === pay.projectId);
		push({
			id: `projpay-${pay.id}`,
			date: pay.expectedDate,
			type: "freelance_expected",
			title: `Jadwal bayar proyek: ${proj?.projectName ?? "Freelance"}`,
			amount: pay.amount,
			detail: "Belum diterima (bukan kas aktual)"
		});
	}
	for (const gc of state.goalContributions) if (gc.date >= monthStart && gc.date <= monthEnd) {
		const goal = state.goals.find((g) => g.id === gc.goalId);
		push({
			id: `gc-${gc.id}`,
			date: gc.date,
			type: "goal_contribution",
			title: `Setor tabungan: ${goal?.name ?? "Target"}`,
			amount: gc.amount
		});
	}
	for (const ns of state.noSpendConfirmations ?? []) if (ns.status === "confirmed" && ns.date >= monthStart && ns.date <= monthEnd) push({
		id: `ns-${ns.date}`,
		date: ns.date,
		type: "no_spend_confirmed",
		title: "Hari Tanpa Jajan Dikonfirmasi",
		detail: ns.note
	});
	for (const cr of state.settings.reminderSettings?.customReminders ?? []) if (cr.enabled && cr.date >= monthStart && cr.date <= monthEnd) push({
		id: `cr-${cr.id}`,
		date: cr.date,
		type: "custom_reminder",
		title: `Pengingat: ${cr.title}`,
		detail: cr.note
	});
	return map;
}
